import{_ as t,a,o as i,a6 as s}from"./chunks/framework.CJDy2q7X.js";const c=JSON.parse('{"title":"Delete Sitemap","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete","title":"Delete Sitemap","description":"Delete a sitemap by id. A successful delete returns no errors; the row and its generated XML files are removed.","query":"mutation DeleteAdminMarketingSitemap(\\n  $input: deleteAdminMarketingSitemapInput!\\n) {\\n  deleteAdminMarketingSitemap(input: $input) {\\n    adminMarketingSitemap {\\n      _id\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/marketing/sitemaps/1\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminMarketingSitemap\\": {\\n      \\"adminMarketingSitemap\\": null\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-delete.md","filePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-delete.md","lastUpdated":1787725411000}'),n={name:"api/graphql-api/admin/marketing/search-seo/sitemaps-delete.md"};function r(d,e,o,l,p,m){return i(),a("div",null,e[0]||(e[0]=[s('<h1 id="delete-sitemap" tabindex="-1">Delete Sitemap <a class="header-anchor" href="#delete-sitemap" aria-label="Permalink to &quot;Delete Sitemap&quot;">​</a></h1><p>Deletes a sitemap — the <strong>Delete</strong> row action on the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen. Removing a sitemap also deletes its generated index and per-batch XML files from storage.</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps/">Sitemaps overview</a> for what a sitemap does and how its fields behave.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminMarketingSitemap</code></td><td>Mutation</td><td>Delete a sitemap</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.search_seo.sitemaps.delete</code> permission.</li><li>Pass the sitemap&#39;s IRI as <code>id</code>. Use the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-list.html">list</a> query to discover valid ids.</li></ul><h3 id="confirm-success-via-the-absence-of-errors" tabindex="-1">Confirm success via the absence of <code>errors</code> <a class="header-anchor" href="#confirm-success-via-the-absence-of-errors" aria-label="Permalink to &quot;Confirm success via the absence of `errors`&quot;">​</a></h3><p>The delete mutation returns a success acknowledgement, not the deleted sitemap&#39;s data — <code>adminMarketingSitemap</code> resolves to <code>null</code> on the payload. <strong>Treat a response with no <code>errors[]</code> as a successful delete.</strong> If you need a confirmation message in the body, use the REST endpoint (<code>DELETE /api/admin/marketing/sitemaps/{id}</code>), which returns <code>{ &quot;message&quot;: &quot;Sitemap deleted.&quot; }</code>.</p><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID</td><td>Yes</td><td>The sitemap&#39;s IRI</td></tr></tbody></table>',11)]))}const u=t(n,[["render",r]]);export{c as __pageData,u as default};
